// === REVERSE LINKED LIST (iterative) ===
function reverseList(head) {
  let prev = null, curr = head;
  while (curr !== null) {
    const next = curr.next; // save before overwriting
    curr.next = prev;       // reverse the pointer
    prev = curr;            // advance prev to current
    curr = next;            // advance curr to saved next
  }
  return prev; // prev is the new head
}

// === FAST/SLOW POINTER (cycle + middle) ===
function fastSlow(head) {
  let slow = head, fast = head;
  while (fast !== null && fast.next !== null) {
    slow = slow.next;        // one step
    fast = fast.next.next;   // two steps
    if (slow === fast) return true; // cycle: they meet
  }
  // no cycle: fast reached null
  // at this point, slow is at the middle of the list
  return slow;
}

// === DUMMY HEAD (remove nth from end) ===
function removeNthFromEnd(head, n) {
  const dummy = { val: 0, next: head };
  let fast = dummy, slow = dummy;
  for (let i = 0; i <= n; i++) fast = fast.next; // fast is n+1 steps ahead
  while (fast) { slow = slow.next; fast = fast.next; }
  slow.next = slow.next.next; // unlink target
  return dummy.next;
}
